{"command": "cat > /tmp/t/srv_proxy.py <<'PYEOF'
import socket, threading, sys, time
LOG=open('/tmp/t/proxy.log','a')
lock=threading.Lock()
def log(s):
    with lock: LOG.write(s+'\n'); LOG.flush()
def tunnel(c, target):
    # connect to target
    host,port = target.split(':')
    try:
        up=socket.create_connection((host,int(port)),3)
    except Exception as e:
        log('UPSTREAM FAIL '+str(e)); c.sendall(b'HTTP/1.1 502 Bad Gateway\r\nContent-Length: 0\r\n\r\n'); c.close(); return
    c.sendall(b'HTTP/1.1 200 Connection established\r\n\r\n')
    sel=[c,up]
    while True:
        import select
        r,_,_=select.select(sel,[],[],5)
        if not r: break
        for x in r:
            try: d=x.recv(65535)
            except Exception: d=b''
            if not d: return
            y = up if x is c else c
            try: y.sendall(d)
            except Exception: return
def handle(c):
    try:
        c.settimeout(5)
        req=b''
        while True:
            d=c.recv(65535)
            if not d: break
            req+=d
            if b'\r\n\r\n' in req: break
        first=req.split(b'\r\n')[0].decode(errors='replace')
        log('=== REQ === '+repr(req))
        if first.startswith('CONNECT'):
            target=first.split(' ')[1]
            tunnel(c,target)
        else:
            c.sendall(b'HTTP/1.1 200 OK\r\nContent-Type: text/html\r\nContent-Length: 16\r\nConnection: close\r\n\r\n<html>x</html>')
    except Exception as e: log('ERR '+repr(e))
    finally:
        try: c.close()
        except Exception: pass
s=socket.socket(); s.setsockopt(socket.SOL_SOCKET,socket.SO_REUSEADDR,1)
s.bind(('127.0.0.1',8500)); s.listen(50)
while True:
    c,_=s.accept(); threading.Thread(target=handle,args=(c,),daemon=True).start()
PYEOF
