// option.go
package main

import (
	"fmt"
	"os"
	"sort"
	"strconv"
	"strings"
	"syscall"
	"unsafe"
)

type optionKind int

const (
	kindBool optionKind = iota
	kindString
	kindInt
	kindUint
	kindStringSlice
)

type option struct {
	short       rune
	long        string
	kind        optionKind
	argName     string   // for value-taking options: "codes"; empty for bool
	choices     []string
	description string
	def         string   // default value as a string ("" = no default)
	// targets
	b *bool
	s *string
	i *int
	u *uint
	l *[]string
}

func (o *option) spec() string {
	var sb strings.Builder
	if o.short != 0 {
		sb.WriteString("-")
		sb.WriteRune(o.short)
		sb.WriteString(", ")
	}
	sb.WriteString("--")
	sb.WriteString(o.long)
	if len(o.choices) > 0 {
		sb.WriteString("=[")
		sb.WriteString(strings.Join(o.choices, "|"))
		sb.WriteString("]")
	} else if o.argName != "" {
		sb.WriteString("=")
		sb.WriteString(o.argName)
		if o.kind == kindStringSlice {
			sb.WriteString("...")
		}
	}
	return sb.String()
}

func (o *option) display() string {
	// "-b, --buffer-size" or "--color"
	if o.short != 0 {
		return fmt.Sprintf("-%c, --%s", o.short, o.long)
	}
	return "--" + o.long
}
