```go
func parse(opts []*option, argv []string) ([]string, error) {
	var positional []string
	byLong := map[string]*option{}
	byShort := map[rune]*option{}
	for _, o := range opts {
		if o.long != "" { byLong[o.long] = o }
		if o.short != 0 { byShort[o.short] = o }
	}
	i := 0
	for i < len(argv) {
		arg := argv[i]
		i++
		if arg == "--" {
			positional = append(positional, argv[i:]...)
			break
		}
		if len(arg) > 1 && arg[0] == '-' {
			if strings.HasPrefix(arg, "--") {
				body := arg[2:]
				name := body
				value := ""
				hasValue := false
				if j := strings.IndexByte(body, '='); j >= 0 {
					name = body[:j]; value = body[j+1:]; hasValue = true
				}
				o, ok := byLong[name]
				if !ok {
					return nil, fmt.Errorf("unknown flag `%s'", name)
				}
				if o.kind == kindBool {
					if hasValue {
						return nil, fmt.Errorf("bool flag `%s' cannot have an argument", o.display())
					}
					*o.b = true
					continue
				}
				if !hasValue {
					// take the next arg
					if i >= len(argv) {
						return nil, fmt.Errorf("expected argument for flag `%s'", o.display())
					}
					next := argv[i]
					if next == "--" {
						return nil, fmt.Errorf("expected argument for flag `%s', but got double dash `--'", o.display())
					}
					if isFlagArg(next) {
						return nil, fmt.Errorf("expected argument for flag `%s', but got option `%s'", o.display(), next)
					}
					value = next
					i++
				}
				if err := o.setValue(value); err != nil { return nil, err }
				continue
			}
			// short flags
			s := arg[1:]
			if len(s) == 0 { /* arg was "-" */ positional = append(positional, arg); continue }
			// inline value check
			if o, ok := byShort[rune(s[0])]; ok && o.kind != kindBool && len(s) > 1 {
				value := s[1:]
				if value[0] == '=' { value = value[1:] }
				if err := o.setValue(value); err != nil { return nil, err }
				continue
			}
			for len(s) > 0 {
				c := rune(s[0])
				o, ok := byShort[c]
				if !ok {
					return nil, fmt.Errorf("unknown flag `%c'", c)
				}
				if o.kind == kindBool {
					*o.b = true
					s = s[1:]
					continue
				}
				// needs an argument
				if len(s) > 1 {
					return nil, fmt.Errorf("expected argument for flag `%s'", o.display())
				}
				// take the next argv element
				if i >= len(argv) {
					return nil, fmt.Errorf("expected argument for flag `%s'", o.display())
				}
				next := argv[i]
				if next == "--" {
					return nil, fmt.Errorf("expected argument for flag `%s', but got double dash `--'", o.display())
				}
				if isFlagArg(next) {
					return nil, fmt.Errorf("expected argument for flag `%s', but got option `%s'", o.display(), next)
				}
				if err := o.setValue(next); err != nil { return nil, err }
				i++
				s = ""
			}
			continue
		}
		positional = append(positional, arg)
	}
	return positional, nil
}
