func parse(opts []*option, argv []string) ([]string, error) {
	var positional []string
	byLong := map[string]*option{}
	byShort := map[rune]*option{}
	for _, o := range opts {
		if o.long != "" { byLong[o.long] = o }
		if o.short != 0 { byShort[o.short] = o }
	}
	i := 0
	for i < len(argv) {
		arg := argv[i]
		i++
		if arg == "--" {
			positional = append(positional, argv[i:]...)
			break
		}
		if len(arg) > 1 && arg[0] == '-' {
			if strings.HasPrefix(arg, "--") {
				body := arg[2:]
				name := body
				value := ""
				hasValue := false
				if j := strings.IndexByte(body, '='); j >= 0 {
					name = body[:j]; value = body[j+1:]; hasValue = true
				}
				o, ok := byLong[name]
				if !ok {
					return nil, fmt.Errorf("unknown flag `%s'", name)
				}
				if o.kind == kindBool {
					if hasValue {
						return nil, fmt.Errorf("bool flag `%s' cannot have an argument", o.display())
					}
					*o.b = true
