func parse(opts []*option, argv []string) ([]string, error) {
	var positional []string
	byLong := map[string]*option{}
	byShort := map[rune]*option{}
	for _, o := range opts {
		if o.long != "" { byLong[o.long] = o }
		if o.short != 0 { byShort[o.short] = o }
	}
