func argumentIsFlag(arg string) bool {
	if arg == "-" || arg == "--" {
		return false
	}
	if strings.HasPrefix(arg, "--") {
		return true
	}
	return strings.HasPrefix(arg, "-") && len(arg) > 1
}

func isNegativeNumber(arg string) bool {
	return len(arg) > 1 && arg[0] == '-' && '0' <= arg[1] && arg[1] <= '9'
}

// parse mimics the behaviour of go-flags' parser.
func (o *options) parse(argv []string) ([]string, error) {
	byLong := make(map[string]*option)
	byShort := make(map[rune]*option)
	for _, opt := range o.list {
		if opt.long != "" {
			byLong[opt.long] = opt
		}
		if opt.short != 0 {
			byShort[opt.short] = opt
		}
	}

	var positional []string
	i := 0
	for i < len(argv) {
		arg := argv[i]
		i++

		if arg == "--" {
			positional = append(positional, argv[i:]...)
			break
		}

		if len(arg) > 1 && arg[0] == '-' {
			if strings.HasPrefix(arg, "--") {
				body := arg[2:]
				name := body
				value := ""
				hasValue := false
				if j := strings.IndexByte(body, '='); j >= 0 {
					name = body[:j]
					value = body[j+1:]
					hasValue = true
				}
				opt, ok := byLong[name]
				if !ok {
					return nil, fmt.Errorf("unknown flag `%s'", name)
				}
				if opt.kind == kindBool {
					if hasValue {
						return nil, fmt.Errorf("bool flag `%s' cannot have an argument", opt.display())
					}
					*opt.b = true
					continue
				}
				if !hasValue {
					if i >= len(argv) {
						return nil, fmt.Errorf("expected argument for flag `%s'", opt.display())
					}
					next := argv[i]
					if next == "--" {
						return nil, fmt.Errorf("expected argument for flag `%s', but got double dash `--'", opt.display())
					}
					if argumentIsFlag(next) && !(opt.isSignedInteger() && isNegativeNumber(next)) {
						return nil, fmt.Errorf("expected argument for flag `%s', but got option `%s'", opt.display(), next)
					}
					value = next
					i++
				}
				if err := opt.setValue(value); err != nil {
					return nil, err
				}
				continue
			}

			s := arg[1:]
			if len(s) == 0 {
				positional = append(positional, arg)
				continue
			}

			if opt, ok := byShort[rune(s[0])]; ok && opt.takesArgument() && len(s) > 1 {
				value := s[1:]
				if value[0] == '=' {
					value = value[1:]
				}
				if err := opt.setValue(value); err != nil {
					return nil, err
				}
				continue
			}

			for len(s) > 0 {
				c := rune(s[0])
				opt, ok := byShort[c]
				if !ok {
					return nil, fmt.Errorf("unknown flag `%c'", c)
				}
				if opt.kind == kindBool {
					*opt.b = true
					s = s[1:]
					continue
				}
				if len(s) > 1 {
					return nil, fmt.Errorf("expected argument for flag `%s'", opt.display())
				}
				if i >= len(argv) {
					return nil, fmt.Errorf("expected argument for flag `%s'", opt.display())
				}
				next := argv[i]
				if next == "--" {
					return nil, fmt.Errorf("expected argument for flag `%s', but got double dash `--'", opt.display())
				}
				if argumentIsFlag(next) && !(opt.isSignedInteger() && isNegativeNumber(next)) {
					return nil, fmt.Errorf("expected argument for flag `%s', but got option `%s'", opt.display(), next)
				}
				if err := opt.setValue(next); err != nil {
					return nil, err
				}
				i++
				s = ""
			}
			continue
		}

		positional = append(positional, arg)
	}

	return positional, nil
}

type winsize struct {
	rows, cols, xpixel, ypixel uint16
}

// terminalWidth returns the width of the controlling terminal.
func terminalWidth() (int, bool) {
	for _, fd := range []int{0, 1, 2} {
		var ws winsize
		_, _, errno := syscall.Syscall(syscall.SYS_IOCTL, uintptr(fd),
			uintptr(syscall.TIOCGWINSZ), uintptr(unsafe.Pointer(&ws)))
		if errno == 0 && ws.cols > 0 {
			return int(ws.cols), true
		}
	}
	return 0, false
}

const defaultTerminalWidth = 80

// wrapText wraps text at the given limit, indenting continuation lines.
func wrapText(s string, limit int, indent string) string {
	var ret string
	words := strings.Split(s, " ")
	line := ""
	for _, word := range words {
		if word == "" {
			continue
		}
		for len(word) > limit {
			if line != "" {
				ret += indent + line + "\n"
				line = ""
			}
			ret += indent + word[:limit-1] + "-\n\n" + indent
			word = word[limit-1:]
		}
		if line == "" {
			line = word
			continue
		}
		if len(line)+1+len(word) <= limit {
			line += " " + word
			continue
		}
		ret += indent + line + "\n"
		line = word
	}
	if line != "" {
		ret += indent + line + "\n"
	}
	return ret
}

// writeHelp writes the help message to the given writer.
func (o *options) writeHelp(program string) {
	width := defaultTerminalWidth
	if w, ok := terminalWidth(); ok {
		width = w
	}

	var b strings.Builder
	b.WriteString("Usage:\n")
	b.WriteString("  " + program + " [options] <url>\n")
	b.WriteString("\n")
	b.WriteString("Application Options:\n")

	column := 0
	for _, opt := range o.list {
		l := len(opt.spec()) + len(opt.prefix())
		if l > column {
			column = l
		}
	}
	column += 4

	indent := strings.Repeat(" ", column)
	limit := width - column
	if limit < 10 {
		limit = 10
	}

	for _, opt := range o.list {
		line := opt.prefix() + opt.spec()
		b.WriteString(line)
		b.WriteString(strings.Repeat(" ", column-len(line)))
		description := opt.description
		if opt.def != "" {
			description += " (default: " + opt.def + ")"
		}
		b.WriteString(wrapText(description, limit, indent))
	}

	fmt.Print(b.String())
}

func (o *option) prefix() string {
	if o.short != 0 {
		return "  "
	}
	return "      "
}
