func (e *errNeedMore) Error() string { return e.err.Error() }

type httpClient struct {
	options  *options
	dnsCache map[string][]net.IP
	dnsMutex sync.Mutex
}

func newHTTPClient(options *options) *httpClient {
	return &httpClient{options: options, dnsCache: make(map[string][]net.IP)}
}

func (c *httpClient) resolver() *net.Resolver {
	if c.options.DNSResolver == "" {
		return &net.Resolver{PreferGo: true}
	}
	address := c.options.DNSResolver
	return &net.Resolver{
		PreferGo: true,
		Dial: func(ctx context.Context, network, addr string) (net.Conn, error) {
			var dialer net.Dialer
			return dialer.DialContext(ctx, "udp", address)
		},
	}
}

func (c *httpClient) lookupIP(host string) ([]net.IP, error) {
	c.dnsMutex.Lock()
	ips, ok := c.dnsCache[host]
	c.dnsMutex.Unlock()
	if ok {
		return ips, nil
	}
	ctx := context.Background()
	if c.options.Timeout != 0 {
		var cancel context.CancelFunc
		ctx, cancel = context.WithTimeout(ctx, time.Duration(c.options.Timeout)*time.Second)
		defer cancel()
	}
	resolved, err := c.resolver().LookupIPAddr(ctx, host)
	if err != nil {
		return nil, err
	}
	var ipv4, ipv6 []net.IP
	for _, ip := range resolved {
		if ip.To4() != nil {
			ipv4 = append(ipv4, ip)
		} else {
			ipv6 = append(ipv6, ip)
		}
	}
	ips = append(ipv4, ipv6...)
	c.dnsMutex.Lock()
	c.dnsCache[host] = ips
	c.dnsMutex.Unlock()
	return ips, nil
}

func (c *httpClient) dialContext(ctx context.Context, network, address string) (net.Conn, error) {
	var dialer net.Dialer
	conn, err := dialer.DialContext(ctx, network, address)
	if err != nil {
		if opErr, ok := err.(*net.OpError); ok {
			return nil, fmt.Errorf("error when dialing %s: %v", opErr.Addr, opErr)
		}
		return nil, err
	}
	return conn, nil
}

func (c *httpClient) dialProxy(ctx context.Context, address string) (net.Conn, error) {
	host, port, err := splitHostPort(address)
	if err != nil {
		return nil, err
	}
	ips, err := net.LookupIP(host)
	if err != nil {
		var dnsErr *net.DNSError
		if errors.As(err, &dnsErr) {
			return nil, dnsErr
		}
		return nil, err
	}
	var ip net.IP
	for _, candidate := range ips {
		if candidate.To4() != nil {
			ip = candidate
			break
		}
	}
	if ip == nil {
		return nil, errors.New("couldn't find DNS entries for the given domain. Try using DialDualStack")
	}
	conn, err := c.dialContext(ctx, "tcp4", net.JoinHostPort(ip.String(), port))
	if err != nil {
		return nil, err
	}
	return conn, nil
}

func splitHostPort(hostport string) (host, port string, err error) {
	host, port, err = net.SplitHostPort(hostport)
	if err != nil {
		return "", "", err
	}
	return host, port, nil
}

func (c *httpClient) connect(ctx context.Context, u *url.URL) (net.Conn, error) {
	host, port, err := splitHostPort(u.Host)
	if err != nil {
		return nil, err
	}
	if port == "" {
		if u.Scheme == "https" {
			port = "443"
		} else {
			port = "80"
		}
	}

	if c.options.Proxy != "" {
		conn, err := c.dialProxy(ctx, c.options.Proxy)
		if err != nil {
			return nil, err
		}
		target := net.JoinHostPort(host, port)
		if err := c.doProxyHandshake(conn, target); err != nil {
			conn.Close()
			return nil, err
		}
		if u.Scheme == "https" {
			conn = c.wrapTLS(conn, host)
		}
		return conn, nil
	}

	ips, err := c.lookupIP(host)
	if err != nil {
		return nil, err
	}
	if len(ips) == 0 {
		return nil, errors.New("couldn't find DNS entries for the given domain. Try using DialDualStack")
	}
	var lastErr error
	for _, ip := range ips {
		conn, err := c.dialContext(ctx, "tcp", net.JoinHostPort(ip.String(), port))
		if err == nil {
			if u.Scheme == "https" {
				conn = c.wrapTLS(conn, host)
			}
			return conn, nil
		}
		lastErr = err
	}
	return nil, lastErr
}

func (c *httpClient) wrapTLS(conn net.Conn, host string) net.Conn {
	config := &tls.Config{ServerName: host}
	if c.options.SkipTLSVerification {
		config.InsecureSkipVerify = true
	}
	return tls.Client(conn, config)
}

func (c *httpClient) doProxyHandshake(conn net.Conn, target string) error {
	request := fmt.Sprintf("CONNECT %s HTTP/1.1\r\nHost: %s\r\n\r\n", target, target)
	if _, err := conn.Write([]byte(request)); err != nil {
		return err
	}
	reader := bufio.NewReader(conn)
	line, err := reader.ReadString('\n')
	if err != nil {
		if line == "" {
			return errConnectionClosed
		}
		return err
	}
	fields := strings.SplitN(line, " ", 3)
	if len(fields) < 2 {
		return errors.New("cannot parse response status code: unexpected first char found. Expecting 0-9")
	}
	code, err := strconv.Atoi(strings.TrimSpace(fields[1]))
	if err != nil {
		return fmt.Errorf("could not connect to proxyAddr: %s status code: %s", c.options.Proxy, strings.TrimSpace(fields[1]))
	}
	if code != 200 {
		return fmt.Errorf("could not connect to proxyAddr: %s status code: %d", c.options.Proxy, code)
	}
	return nil
}

type requestHeader struct {
	userAgent     string
	host          string
	contentType   string
	contentLength string
	connection    string
	cookie        []string
	trailer       string
	authorization string
	others        map[string][]string
}

func (c *httpClient) buildRequestHeader(u *url.URL, authorization string) requestHeader {
	h := requestHeader{others: make(map[string][]string)}
	for _, raw := range c.options.Header {
		i := strings.IndexByte(raw, ':')
		if i < 0 {
			continue
		}
		key := canonicalMIMEHeaderKey(raw[:i])
		value := strings.TrimSpace(raw[i+1:])
		switch strings.ToLower(key) {
		case "user-agent":
			h.userAgent = value
		case "host":
			// ignore
		case "content-type":
			h.contentType = value
		case "content-length":
			h.contentLength = value
		case "connection":
			h.connection = value
		case "transfer-encoding":
			// ignore
		case "cookie":
			h.cookie = append(h.cookie, value)
		case "trailer":
			h.trailer = value
		default:
			h.others[key] = append(h.others[key], value)
		}
	}
	if _, ok := h.others["Accept"]; !ok {
		h.others["Accept"] = []string{"*/*"}
	}
	if authorization != "" {
		if _, ok := h.others["Authorization"]; !ok {
			h.authorization = authorization
		}
	}
	h.host = u.Host
	return h
}

func (h *requestHeader) write(uri string) []byte {
	var b bytes.Buffer
	b.WriteString("GET ")
	b.WriteString(uri)
	b.WriteString(" HTTP/1.1\r\n")
	if h.userAgent != "" {
		b.WriteString("User-Agent: ")
		b.WriteString(h.userAgent)
		b.WriteString("\r\n")
	}
	b.WriteString("Host: ")
	b.WriteString(h.host)
	b.WriteString("\r\n")
	if h.contentType != "" {
		b.WriteString("Content-Type: ")
		b.WriteString(h.contentType)
		b.WriteString("\r\n")
	}
	if h.contentLength != "" {
		b.WriteString("Content-Length: ")
		b.WriteString(h.contentLength)
		b.WriteString("\r\n")
	}
	if h.connection != "" {
		b.WriteString("Connection: ")
		b.WriteString(h.connection)
		b.WriteString("\r\n")
	}
	for key, values := range h.others {
		for _, value := range values {
			b.WriteString(key)
			b.WriteString(": ")
			b.WriteString(value)
			b.WriteString("\r\n")
		}
	}
	if h.authorization != "" {
		b.WriteString("Authorization: ")
		b.WriteString(h.authorization)
		b.WriteString("\r\n")
	}
	if len(h.cookie) > 0 {
		b.WriteString("Cookie: ")
		b.WriteString(strings.Join(h.cookie, "; "))
		b.WriteString("\r\n")
	}
	if h.trailer != "" {
		b.WriteString("Trailer: ")
		b.WriteString(h.trailer)
		b.WriteString("\r\n")
	}
	if h.connection == "" {
		b.WriteString("Connection: close\r\n")
	}
	b.WriteString("\r\n")
	return b.Bytes()
}

func canonicalMIMEHeaderKey(key string) string {
	if key == "" {
		return ""
	}
	upper := true
	for i := 0; i < len(key); i++ {
		c := key[i]
		if !validHeaderFieldByte(c) {
			return key
		}
	}
	out := []byte(key)
	for i := 0; i < len(out); i++ {
		c := out[i]
		if upper && 'a' <= c && c <= 'z' {
			c -= 'a' - 'A'
		} else if !upper && 'A' <= c && c <= 'Z' {
			c += 'a' - 'A'
		}
		out[i] = c
		upper = c == '-'
	}
	return string(out)
}

func validHeaderFieldByte(c byte) bool {
	return 'a' <= c && c <= 'z' || 'A' <= c && c <= 'Z' || '0' <= c && c <= '9' ||
		c == '-' || c == '_' || c == '.' || c == ' ' || c == '"' || c == '(' || c == ')' ||
		c == ',' || c == '/' || c == ':' || c == ';' || c == '<' || c == '=' || c == '>' ||
		c == '?' || c == '@' || c == '[' || c == '\\' || c == ']' || c == '{' || c == '}' ||
		c == '!' || c == '#' || c == '$' || c == '%' || c == '&' || c == '\'' || c == '*' ||
		c == '+' || c == '^' || c == '`' || c == '|' || c == '~'
}

func (c *httpClient) Get(rawurl string) (*response, error) {
	u, err := url.Parse(rawurl)
	if err != nil {
		return nil, err
	}
	switch u.Scheme {
	case "http", "https":
	default:
		return nil, fmt.Errorf("unsupported protocol %q. http and https are supported", u.Scheme)
	}

	ctx := context.Background()
	if c.options.Timeout != 0 {
		var cancel context.CancelFunc
		ctx, cancel = context.WithTimeout(ctx, time.Duration(c.options.Timeout)*time.Second)
		defer cancel()
	}

	conn, err := c.connect(ctx, u)
	if err != nil {
		return nil, err
	}
	defer conn.Close()

	authorization := ""
	if u.User != nil {
		password, _ := u.User.Password()
		authorization = "Basic " + base64Encode(u.User.Username() + ":" + password)
	}
	h := c.buildRequestHeader(u, authorization)
	uri := u.Path
	if u.RawQuery != "" {
		if uri == "" {
			uri = "?" + u.RawQuery
		} else {
			uri += "?" + u.RawQuery
		}
	}
	if uri == "" {
		uri = "/"
	}
	if _, err := conn.Write(h.write(uri)); err != nil {
		return nil, err
	}

	return c.readResponse(conn, u)
}

func base64Encode(s string) string {
	const alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
	var b bytes.Buffer
	data := []byte(s)
	for i := 0; i < len(data); i += 3 {
		var chunk [3]byte
		n := copy(chunk[:], data[i:])
		b.WriteByte(alphabet[chunk[0]>>2])
		b.WriteByte(alphabet[(chunk[0]&0x03)<<4|chunk[1]>>4])
		if n > 1 {
			b.WriteByte(alphabet[(chunk[1]&0x0f)<<2|chunk[2]>>6])
		} else {
			b.WriteByte('=')
		}
		if n > 2 {
			b.WriteByte(alphabet[chunk[2]&0x3f])
		} else {
			b.WriteByte('=')
		}
	}
	return b.String()
}

func (c *httpClient) readResponse(conn net.Conn, u *url.URL) (*response, error) {
	size := c.options.BufferSize
	if size < 16 {
		size = 16
	}
	reader := bufio.NewReaderSize(conn, size)

	n := 1
	var buf []byte
	var headerLen int
	var status int
	for i := 0; i < 8; i++ {
		b, err := reader.Peek(n)
		if len(b) == 0 {
			if err != nil {
				if err == io.EOF {
					return nil, headerError(errors.New("EOF"), b)
				}
				return nil, err
			}
			return nil, headerError(errSmallReadBuffer, b)
		}
		if err != nil && err != io.EOF {
			return nil, err
		}
		buf = b
		headerLen, status, err = parseResponseHeader(buf)
		if err == nil {
			break
		}
		if _, ok := err.(*errNeedMore); !ok {
			return nil, headerError(err, buf)
		}
		if len(buf) == size {
			return nil, headerError(errSmallReadBuffer, buf)
		}
		if err.(*errNeedMore).err == io.EOF {
			return nil, headerError(errors.New("EOF"), buf)
		}
		n *= 2
	}
	if headerLen < 0 {
		return nil, headerError(errors.New("EOF"), buf)
	}
	reader.Discard(headerLen)

	resp := &response{status: status, url: u.String()}
	var rest []byte
	rest, err := readBody(reader, buf[headerLen:], c.options.MaxResponseBodySize)
	if err != nil {
		return nil, err
	}
	_ = rest
	return resp, nil
}

func headerError(err error, buf []byte) error {
	var inner string
	switch e := err.(type) {
	case *errNeedMore:
		inner = e.err.Error()
	default:
		inner = err.Error()
	}
	return fmt.Errorf("error when reading response headers: %s. Buffer size=%d, contents: %q", inner, len(buf), buf)
}
