type header struct {
	key   string
	value string
}

// response represents a parsed HTTP response.
type response struct {
	status      int
	headers     []header
	body        []byte
	contentType string
	url         string
}

func (r *response) headerValue(name string) string {
	for _, h := range r.headers {
		if strings.EqualFold(h.key, name) {
			return h.value
		}
	}
	return ""
}

var (
	errConnectionClosed = errors.New("the server closed connection before returning the first response byte. " +
		"Make sure the server returns 'Connection: close' response header before closing the connection")
	errSmallReadBuffer = errors.New("small read buffer. Increase ReadBufferSize")
)

// needMore signals that more data is needed to parse the response headers.
type needMore struct{}

func (e *needMore) Error() string { return "need more" }

type respHeader struct {
	status      int
	headers     []header
	contentType string
	bodyOffset  int
}

type httpClient struct {
	options  *options
	dnsCache map[string][]net.IP
	dnsMutex sync.Mutex
}

func newHTTPClient(options *options) *httpClient {
	return &httpClient{options: options, dnsCache: make(map[string][]net.IP)}
}

func (c *httpClient) resolver() *net.Resolver {
	if c.options.DNSResolver == "" {
		return &net.Resolver{PreferGo: true}
	}
	address := c.options.DNSResolver
	return &net.Resolver{
		PreferGo: true,
		Dial: func(ctx context.Context, network, addr string) (net.Conn, error) {
			var dialer net.Dialer
			return dialer.DialContext(ctx, "udp", address)
		},
	}
}

func (c *httpClient) lookupIP(host string) ([]net.IP, error) {
	c.dnsMutex.Lock()
	ips, ok := c.dnsCache[host]
	c.dnsMutex.Unlock()
	if ok {
		return ips, nil
	}
	ctx := context.Background()
	if c.options.Timeout > 0 {
		var cancel context.CancelFunc
		ctx, cancel = context.WithTimeout(ctx, time.Duration(c.options.Timeout)*time.Second)
		defer cancel()
	}
	resolved, err := c.resolver().LookupIPAddr(ctx, host)
	if err != nil {
		return nil, err
	}
	var ipv4, ipv6 []net.IP
	for _, ip := range resolved {
		if ip.To4() != nil {
			ipv4 = append(ipv4, ip)
		} else {
			ipv6 = append(ipv6, ip)
		}
	}
	ips = append(ipv4, ipv6...)
	c.dnsMutex.Lock()
	c.dnsCache[host] = ips
	c.dnsMutex.Unlock()
	return ips, nil
}

func dial(ctx context.Context, network, address string) (net.Conn, error) {
	var dialer net.Dialer
	conn, err := dialer.DialContext(ctx, network, address)
	if err != nil {
		if opErr, ok := err.(*net.OpError); ok {
			return nil, fmt.Errorf("error when dialing %s: %v", opErr.Addr, opErr)
		}
		return nil, err
	}
	return conn, nil
}

func (c *httpClient) dialProxy(ctx context.Context, address string) (net.Conn, error) {
	host, port, err := net.SplitHostPort(address)
	if err != nil {
		return nil, err
	}
	ips, err := net.LookupIP(host)
	if err != nil {
		return nil, err
	}
	var ip net.IP
	for _, candidate := range ips {
		if candidate.To4() != nil {
			ip = candidate
			break
		}
	}
	if ip == nil {
		return nil, errors.New("couldn't find DNS entries for the given domain. Try using DialDualStack")
	}
	return dial(ctx, "tcp4", net.JoinHostPort(ip.String(), port))
}

func (c *httpClient) wrapTLS(conn net.Conn, host string) net.Conn {
	config := &tls.Config{ServerName: host}
	if c.options.SkipTLSVerification {
		config.InsecureSkipVerify = true
	}
	return tls.Client(conn, config)
}

func (c *httpClient) doProxyHandshake(conn net.Conn, target string) error {
	request := fmt.Sprintf("CONNECT %s HTTP/1.1\r\nHost: %s\r\n\r\n", target, target)
	if _, err := conn.Write([]byte(request)); err != nil {
		return err
	}
	reader := bufio.NewReader(conn)
	line, err := reader.ReadString('\n')
	if err != nil {
		if line == "" {
			return errConnectionClosed
		}
		return err
	}
	fields := strings.SplitN(strings.TrimRight(line, "\r\n"), " ", 3)
	if len(fields) < 2 {
		return errors.New("cannot parse response status code: unexpected first char found. Expecting 0-9")
	}
	code, convErr := strconv.Atoi(fields[1])
	if convErr != nil {
		return fmt.Errorf("could not connect to proxyAddr: %s status code: %s", c.options.Proxy, fields[1])
	}
	if code != 200 {
		return fmt.Errorf("could not connect to proxyAddr: %s status code: %d", c.options.Proxy, code)
	}
	return nil
}

func (c *httpClient) connect(ctx context.Context, u *url.URL) (net.Conn, error) {
	host, port, err := net.SplitHostPort(u.Host)
	if err != nil {
		return nil, err
	}
	if port == "" {
		if u.Scheme == "https" {
			port = "443"
		} else {
			port = "80"
		}
	}

	if c.options.Proxy != "" {
		conn, err := c.dialProxy(ctx, c.options.Proxy)
		if err != nil {
			return nil, err
		}
		target := net.JoinHostPort(host, port)
		if err := c.doProxyHandshake(conn, target); err != nil {
			conn.Close()
			return nil, err
		}
		if u.Scheme == "https" {
			conn = c.wrapTLS(conn, host)
		}
		return conn, nil
	}

	ips, err := c.lookupIP(host)
	if err != nil {
		return nil, err
	}
	if len(ips) == 0 {
		return nil, errors.New("couldn't find DNS entries for the given domain. Try using DialDualStack")
	}
	var lastErr error
	for _, ip := range ips {
		conn, err := dial(ctx, "tcp", net.JoinHostPort(ip.String(), port))
		if err == nil {
			if u.Scheme == "https" {
				conn = c.wrapTLS(conn, host)
			}
			return conn, nil
		}
		lastErr = err
	}
	return nil, lastErr
}

