}

func base64Encode(s string) string {
	const alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
	var b bytes.Buffer
	data := []byte(s)
	for i := 0; i < len(data); i += 3 {
		var chunk [3]byte
		n := copy(chunk[:], data[i:])
		b.WriteByte(alphabet[chunk[0]>>2])
		b.WriteByte(alphabet[(chunk[0]&0x03)<<4|chunk[1]>>4])
		if n > 1 {
			b.WriteByte(alphabet[(chunk[1]&0x0f)<<2|chunk[2]>>6])
		} else {
			b.WriteByte('=')
		}
		if n > 2 {
			b.WriteByte(alphabet[chunk[2]&0x3f])
		} else {
			b.WriteByte('=')
		}
	}
	return b.String()
}

func (c *httpClient) readResponse(conn net.Conn, u *url.URL) (*response, error) {
	size := c.options.BufferSize
	if size < 16 {
		size = 16
	}
	reader := bufio.NewReaderSize(conn, size)

	n := 1
	var buf []byte
	var rh *respHeader
	for {
		b, peekErr := reader.Peek(n)
		if len(b) == 0 {
			if peekErr == io.EOF {
				return nil, headerError(errors.New("EOF"), b)
			}
			if peekErr != nil {
				return nil, peekErr
			}
			return nil, headerError(errSmallReadBuffer, b)
		}
		if peekErr != nil && peekErr != io.EOF && peekErr != bufio.ErrBufferFull {
			return nil, peekErr
		}
		buf = b
		h, parseErr := parseResponseHeader(buf)
		if parseErr == nil {
			rh = h
			break
		}
		if _, ok := parseErr.(*needMore); !ok {
			return nil, headerError(parseErr, buf)
		}
		if peekErr == io.EOF {
			return nil, headerError(errors.New("EOF"), buf)
		}
		if len(buf) == size {
			return nil, headerError(errSmallReadBuffer, buf)
		}
		n *= 2
		if n > size {
			n = size
		}
	}
	reader.Discard(rh.bodyOffset)

	resp := &response{status: rh.status, headers: rh.headers, contentType: rh.contentType}
	body, err := readBody(reader, buf[rh.bodyOffset:], c.options.MaxResponseBodySize)
	if err != nil {
		return nil, err
	}
	resp.body = body
	return resp, nil
}

