	connection    string
	cookie        []string
	trailer       string
	authorization string
	others        map[string][]string
}

func buildRequestHeader(host, authorization string, raw []string) *requestHeader {
	h := &requestHeader{others: make(map[string][]string)}
	for _, r := range raw {
		i := strings.IndexByte(r, ':')
		if i < 0 {
			continue
		}
		key := canonicalMIMEHeaderKey(r[:i])
		value := strings.TrimSpace(r[i+1:])
		switch strings.ToLower(key) {
		case "user-agent":
			h.userAgent = value
		case "host":
			// ignore
		case "content-type":
			h.contentType = value
		case "content-length":
			h.contentLength = value
		case "connection":
			h.connection = value
		case "transfer-encoding":
			// ignore
		case "cookie":
			h.cookie = append(h.cookie, value)
		case "trailer":
