	b.WriteString("\r\n")
	if h.contentType != "" {
		b.WriteString("Content-Type: ")
		b.WriteString(h.contentType)
		b.WriteString("\r\n")
	}
	if h.contentLength != "" {
		b.WriteString("Content-Length: ")
		b.WriteString(h.contentLength)
		b.WriteString("\r\n")
	}
	if h.connection != "" {
		b.WriteString("Connection: ")
		b.WriteString(h.connection)
		b.WriteString("\r\n")
	}
	for key, values := range h.others {
		for _, value := range values {
			b.WriteString(key)
			b.WriteString(": ")
			b.WriteString(value)
