		b.WriteString(h.trailer)
		b.WriteString("\r\n")
	}
	if h.connection == "" {
		b.WriteString("Connection: close\r\n")
	}
	b.WriteString("\r\n")
	return b.Bytes()
}

func canonicalMIMEHeaderKey(key string) string {
	for i := 0; i < len(key); i++ {
		if !validHeaderFieldByte(key[i]) {
			return key
		}
	}
	upper := true
	out := []byte(key)
	for i := 0; i < len(out); i++ {
		c := out[i]
		if upper && 'a' <= c && c <= 'z' {
			c -= 'a' - 'A'
		} else if !upper && 'A' <= c && c <= 'Z' {
			c += 'a' - 'A'
		}
		out[i] = c
		upper = c == '-'
	}
	return string(out)
}

func validHeaderFieldByte(c byte) bool {
	switch {
	case 'a' <= c && c <= 'z', 'A' <= c && c <= 'Z', '0' <= c && c <= '9':
		return true
	}
	switch c {
	case '-', '_', '.', ' ', '"', '(', ')', ',', '/', ':', ';', '<', '=', '>', '?', '@',
		'[', '\\', ']', '{', '}', '!', '#', '$', '%', '&', '\'', '*', '+', '^', '`', '|', '~':
		return true
	}
	return false
}
