}

type httpClient struct {
	options  *options
	dnsCache map[string][]net.IP
	dnsMutex sync.Mutex
}

func newHTTPClient(options *options) *httpClient {
	return &httpClient{options: options, dnsCache: make(map[string][]net.IP)}
}

func (c *httpClient) resolver() *net.Resolver {
	if c.options.DNSResolver == "" {
		return &net.Resolver{PreferGo: true}
	}
	address := c.options.DNSResolver
	return &net.Resolver{
		PreferGo: true,
		Dial: func(ctx context.Context, network, addr string) (net.Conn, error) {
			var dialer net.Dialer
			return dialer.DialContext(ctx, "udp", address)
		},
	}
}

func (c *httpClient) lookupIP(host string) ([]net.IP, error) {
	c.dnsMutex.Lock()
	ips, ok := c.dnsCache[host]
	c.dnsMutex.Unlock()
	if ok {
		return ips, nil
	}
	ctx := context.Background()
	if c.options.Timeout > 0 {
		var cancel context.CancelFunc
		ctx, cancel = context.WithTimeout(ctx, time.Duration(c.options.Timeout)*time.Second)
		defer cancel()
	}
	resolved, err := c.resolver().LookupIPAddr(ctx, host)
	if err != nil {
		return nil, err
	}
	var ipv4, ipv6 []net.IP
	for _, ip := range resolved {
		if ip.To4() != nil {
			ipv4 = append(ipv4, ip)
		} else {
			ipv6 = append(ipv6, ip)
		}
	}
	ips = append(ipv4, ipv6...)
	c.dnsMutex.Lock()
	c.dnsCache[host] = ips
	c.dnsMutex.Unlock()
	return ips, nil
}

func dial(ctx context.Context, network, address string) (net.Conn, error) {
	var dialer net.Dialer
	conn, err := dialer.DialContext(ctx, network, address)
	if err != nil {
		if opErr, ok := err.(*net.OpError); ok {
			return nil, fmt.Errorf("error when dialing %s: %v", opErr.Addr, opErr)
		}
		return nil, err
	}
	return conn, nil
}

func (c *httpClient) dialProxy(ctx context.Context, address string) (net.Conn, error) {
	host, port, err := net.SplitHostPort(address)
	if err != nil {
		return nil, err
	}
	ips, err := net.LookupIP(host)
	if err != nil {
		return nil, err
	}
	var ip net.IP
	for _, candidate := range ips {
		if candidate.To4() != nil {
			ip = candidate
			break
		}
	}
	if ip == nil {
		return nil, errors.New("couldn't find DNS entries for the given domain. Try using DialDualStack")
	}
	return dial(ctx, "tcp4", net.JoinHostPort(ip.String(), port))
}

func (c *httpClient) wrapTLS(conn net.Conn, host string) net.Conn {
	config := &tls.Config{ServerName: host}
	if c.options.SkipTLSVerification {
		config.InsecureSkipVerify = true
	}
	return tls.Client(conn, config)
}

func (c *httpClient) doProxyHandshake(conn net.Conn, target string) error {
	request := fmt.Sprintf("CONNECT %s HTTP/1.1\r\nHost: %s\r\n\r\n", target, target)
	if _, err := conn.Write([]byte(request)); err != nil {
		return err
	}
	reader := bufio.NewReader(conn)
	line, err := reader.ReadString('\n')
	if err != nil {
		if line == "" {
			return errConnectionClosed
		}
		return err
	}
	fields := strings.SplitN(strings.TrimRight(line, "\r\n"), " ", 3)
	if len(fields) < 2 {
		return errors.New("cannot parse response status code: unexpected first char found. Expecting 0-9")
	}
	code, convErr := strconv.Atoi(fields[1])
	if convErr != nil {
		return fmt.Errorf("could not connect to proxyAddr: %s status code: %s", c.options.Proxy, fields[1])
	}
	if code != 200 {
		return fmt.Errorf("could not connect to proxyAddr: %s status code: %d", c.options.Proxy, code)
	}
	return nil
}

func (c *httpClient) connect(ctx context.Context, u *url.URL) (net.Conn, error) {
	host, port, err := net.SplitHostPort(u.Host)
	if err != nil {
		return nil, err
	}
	if port == "" {
		if u.Scheme == "https" {
			port = "443"
		} else {
			port = "80"
		}
	}

	if c.options.Proxy != "" {
		conn, err := c.dialProxy(ctx, c.options.Proxy)
		if err != nil {
			return nil, err
		}
		target := net.JoinHostPort(host, port)
		if err := c.doProxyHandshake(conn, target); err != nil {
			conn.Close()
			return nil, err
		}
		if u.Scheme == "https" {
			conn = c.wrapTLS(conn, host)
		}
		return conn, nil
	}

	ips, err := c.lookupIP(host)
	if err != nil {
		return nil, err
	}
	if len(ips) == 0 {
		return nil, errors.New("couldn't find DNS entries for the given domain. Try using DialDualStack")
	}
	var lastErr error
	for _, ip := range ips {
		conn, err := dial(ctx, "tcp", net.JoinHostPort(ip.String(), port))
		if err == nil {
			if u.Scheme == "https" {
				conn = c.wrapTLS(conn, host)
			}
			return conn, nil
		}
		lastErr = err
	}
	return nil, lastErr
}

func (c *httpClient) Get(rawurl string) (*response, error) {
	u, err := url.Parse(rawurl)
	if err != nil {
		return nil, err
	}
	switch u.Scheme {
	case "http", "https":
	default:
		return nil, fmt.Errorf("unsupported protocol %q. http and https are supported", u.Scheme)
	}

	ctx := context.Background()
	if c.options.Timeout > 0 {
		var cancel context.CancelFunc
		ctx, cancel = context.WithTimeout(ctx, time.Duration(c.options.Timeout)*time.Second)
		defer cancel()
	}

	conn, err := c.connect(ctx, u)
	if err != nil {
		return nil, err
	}
	defer conn.Close()

	authorization := ""
	if u.User != nil {
		password, _ := u.User.Password()
		authorization = "Basic " + base64Encode(u.User.Username()+":"+password)
	}
	uri := u.Path
	if u.RawQuery != "" {
		if uri == "" {
			uri = "?" + u.RawQuery
		} else {
			uri += "?" + u.RawQuery
		}
	}
	if uri == "" {
		uri = "/"
	}
	request := buildRequestHeader(u.Host, authorization, c.options.Header).write(uri)
	if _, err := conn.Write(request); err != nil {
		return nil, err
	}

	resp, err := c.readResponse(conn, u)
	if err != nil {
		return nil, err
	}
	resp.url = u.String()
	return resp, nil
}

func base64Encode(s string) string {
	const alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
	var b bytes.Buffer
	data := []byte(s)
	for i := 0; i < len(data); i += 3 {
		var chunk [3]byte
		n := copy(chunk[:], data[i:])
		b.WriteByte(alphabet[chunk[0]>>2])
		b.WriteByte(alphabet[(chunk[0]&0x03)<<4|chunk[1]>>4])
		if n > 1 {
			b.WriteByte(alphabet[(chunk[1]&0x0f)<<2|chunk[2]>>6])
		} else {
			b.WriteByte('=')
		}
		if n > 2 {
			b.WriteByte(alphabet[chunk[2]&0x3f])
		} else {
			b.WriteByte('=')
		}
	}
	return b.String()
}

func (c *httpClient) readResponse(conn net.Conn, u *url.URL) (*response, error) {
	size := c.options.BufferSize
	if size < 16 {
		size = 16
	}
	reader := bufio.NewReaderSize(conn, size)

	n := 1
	var buf []byte
	var rh *respHeader
	for {
		b, peekErr := reader.Peek(n)
		if len(b) == 0 {
			if peekErr == io.EOF {
				return nil, headerError(errors.New("EOF"), b)
			}
			if peekErr != nil {
				return nil, peekErr
			}
			return nil, headerError(errSmallReadBuffer, b)
		}
		if peekErr != nil && peekErr != io.EOF && peekErr != bufio.ErrBufferFull {
			return nil, peekErr
		}
		buf = b
		h, parseErr := parseResponseHeader(buf)
		if parseErr == nil {
			rh = h
			break
		}
		if _, ok := parseErr.(*needMore); !ok {
			return nil, headerError(parseErr, buf)
		}
		if peekErr == io.EOF {
			return nil, headerError(errors.New("EOF"), buf)
		}
		if len(buf) == size {
			return nil, headerError(errSmallReadBuffer, buf)
		}
		n *= 2
		if n > size {
			n = size
		}
	}
	reader.Discard(rh.bodyOffset)

	resp := &response{status: rh.status, headers: rh.headers, contentType: rh.contentType}
	body, err := readBody(reader, buf[rh.bodyOffset:], c.options.MaxResponseBodySize)
	if err != nil {
		return nil, err
	}
	resp.body = body
	return resp, nil
}

func headerError(err error, buf []byte) error {
	return fmt.Errorf("error when reading response headers: %s. Buffer size=%d, contents: %q", err.Error(), len(buf), buf)
}

func isDigit(c byte) bool { return '0' <= c && c <= '9' }

func parseResponseHeader(b []byte) (*respHeader, error) {
	i := 0
	for i < len(b) && (b[i] == '\r' || b[i] == '\n') {
		i++
	}
	j := i
	for j+1 < len(b) {
		if b[j] == '\r' && b[j+1] == '\n' {
			break
		}
		j++
	}
	if j+1 >= len(b) {
		return nil, &needMore{}
	}
	firstLine := b[i : j+2]
	k := bytes.IndexByte(firstLine, ' ')
	if k < 0 {
		return nil, fmt.Errorf("cannot find whitespace in the first line of response %q", firstLine)
	}
	rest := firstLine[k+1:]
	if len(rest) == 0 || !isDigit(rest[0]) {
		return nil, fmt.Errorf("cannot parse response status code: unexpected first char found. Expecting 0-9. Response %q", b)
	}
	m := 0
	for m < len(rest) && isDigit(rest[m]) {
		m++
	}
	status, convErr := strconv.Atoi(string(rest[:m]))
	if convErr != nil {
		return nil, fmt.Errorf("cannot parse response status code: unexpected first char found. Expecting 0-9. Response %q", b)
	}
	if m < len(rest) && rest[m] != ' ' && rest[m] != '\r' {
		return nil, fmt.Errorf("unexpected char at the end of status code. Response %q", b)
	}

	h := &respHeader{status: status}
	pos := j + 2
	var contentLength int64
	hasContentLength := false
	chunked := false
	for {
		k := pos
		for k+1 < len(b) {
			if b[k] == '\r' && b[k+1] == '\n' {
				break
			}
			k++
		}
		if k+1 >= len(b) {
			return nil, &needMore{}
		}
		if k == pos {
			pos += 2
			break
		}
		line := b[pos:k]
		pos = k + 2
		ci := bytes.IndexByte(line, ':')
		if ci < 0 {
			continue
		}
		key := string(bytes.TrimRight(line[:ci], " "))
		value := string(bytes.TrimLeft(line[ci+1:], " \t"))
		h.headers = append(h.headers, header{key: key, value: value})
		switch {
		case strings.EqualFold(key, "Content-Type"):
			h.contentType = value
		case strings.EqualFold(key, "Content-Length"):
			hasContentLength = true
			cl, err := parsePositiveInt(value)
			if err != nil {
				return nil, err
			}
			contentLength = cl
		case strings.EqualFold(key, "Transfer-Encoding"):
			if strings.Contains(strings.ToLower(value), "chunked") {
				chunked = true
			}
		}
	}
	h.bodyOffset = pos
	h.headers = append(h.headers, header{key: "__bodyLength", value: strconv.FormatInt(contentLength, 10)})
	if hasContentLength {
		h.headers = append(h.headers, header{key: "__hasContentLength", value: "1"})
	}
	if chunked {
		h.headers = append(h.headers, header{key: "__chunked", value: "1"})
	}
	return h, nil
}

func parsePositiveInt(v string) (int64, error) {
	if len(v) == 0 || !isDigit(v[0]) {
		return 0, fmt.Errorf("cannot parse Content-Length: unexpected first char found. Expecting 0-9.")
	}
	i := 0
	for i < len(v) && isDigit(v[i]) {
		i++
	}
	if i < len(v) {
		return 0, fmt.Errorf("cannot parse Content-Length: unexpected char at the end of Content-Length.")
	}
	n, err := strconv.ParseInt(v[:i], 10, 64)
	if err != nil {
		return 0, fmt.Errorf("cannot parse Content-Length: %v", err)
	}
	return n, nil
}

func readBody(reader *bufio.Reader, rest []byte, maxSize int) ([]byte, error) {
	_ = rest
	if maxSize <= 0 {
		maxSize = 1 << 30
	}
	b, err := io.ReadAll(io.LimitReader(reader, int64(maxSize)+1))
	if err != nil && err != io.EOF {
		return nil, err
	}
	if len(b) > maxSize {
		return nil, errors.New("body size exceeds the given limit")
	}
	return b, nil
}

type requestHeader struct {
	userAgent     string
	host          string
	contentType   string
	contentLength string
	connection    string
	cookie        []string
	trailer       string
	authorization string
	others        map[string][]string
}

func buildRequestHeader(host, authorization string, raw []string) *requestHeader {
	h := &requestHeader{others: make(map[string][]string)}
	for _, r := range raw {
		i := strings.IndexByte(r, ':')
		if i < 0 {
			continue
		}
		key := canonicalMIMEHeaderKey(r[:i])
		value := strings.TrimSpace(r[i+1:])
		switch strings.ToLower(key) {
		case "user-agent":
			h.userAgent = value
		case "host":
			// ignore
		case "content-type":
			h.contentType = value
		case "content-length":
			h.contentLength = value
		case "connection":
			h.connection = value
		case "transfer-encoding":
			// ignore
		case "cookie":
			h.cookie = append(h.cookie, value)
		case "trailer":
			h.trailer = value
		default:
			h.others[key] = append(h.others[key], value)
		}
	}
	if _, ok := h.others["Accept"]; !ok {
		h.others["Accept"] = []string{"*/*"}
	}
	if authorization != "" {
		if _, ok := h.others["Authorization"]; !ok {
			h.authorization = authorization
		}
	}
	h.host = host
	return h
}

func (h *requestHeader) write(uri string) []byte {
	var b bytes.Buffer
	b.WriteString("GET ")
	b.WriteString(uri)
	b.WriteString(" HTTP/1.1\r\n")
	if h.userAgent != "" {
		b.WriteString("User-Agent: ")
		b.WriteString(h.userAgent)
		b.WriteString("\r\n")
	}
	b.WriteString("Host: ")
	b.WriteString(h.host)
	b.WriteString("\r\n")
	if h.contentType != "" {
		b.WriteString("Content-Type: ")
		b.WriteString(h.contentType)
		b.WriteString("\r\n")
	}
	if h.contentLength != "" {
		b.WriteString("Content-Length: ")
		b.WriteString(h.contentLength)
		b.WriteString("\r\n")
	}
	if h.connection != "" {
		b.WriteString("Connection: ")
		b.WriteString(h.connection)
		b.WriteString("\r\n")
	}
	for key, values := range h.others {
		for _, value := range values {
			b.WriteString(key)
			b.WriteString(": ")
			b.WriteString(value)
			b.WriteString("\r\n")
		}
	}
	if h.authorization != "" {
		b.WriteString("Authorization: ")
		b.WriteString(h.authorization)
		b.WriteString("\r\n")
	}
	if len(h.cookie) > 0 {
		b.WriteString("Cookie: ")
		b.WriteString(strings.Join(h.cookie, "; "))
		b.WriteString("\r\n")
	}
	if h.trailer != "" {
		b.WriteString("Trailer: ")
		b.WriteString(h.trailer)
		b.WriteString("\r\n")
	}
	if h.connection == "" {
		b.WriteString("Connection: close\r\n")
	}
	b.WriteString("\r\n")
	return b.Bytes()
}

func canonicalMIMEHeaderKey(key string) string {
	for i := 0; i < len(key); i++ {
		if !validHeaderFieldByte(key[i]) {
			return key
		}
	}
	upper := true
	out := []byte(key)
	for i := 0; i < len(out); i++ {
		c := out[i]
		if upper && 'a' <= c && c <= 'z' {
			c -= 'a' - 'A'
		} else if !upper && 'A' <= c && c <= 'Z' {
			c += 'a' - 'A'
		}
		out[i] = c
		upper = c == '-'
	}
	return string(out)
}

func validHeaderFieldByte(c byte) bool {
	switch {
	case 'a' <= c && c <= 'z', 'A' <= c && c <= 'Z', '0' <= c && c <= '9':
		return true
	}
	switch c {
	case '-', '_', '.', ' ', '"', '(', ')', ',', '/', ':', ';', '<', '=', '>', '?', '@',
		'[', '\\', ']', '{', '}', '!', '#', '$', '%', '&', '\'', '*', '+', '^', '`', '|', '~':
		return true
	}
	return false
}
