package main

import "sync"

type hostThrottler struct {
	mutex       sync.Mutex
	semaphores  map[string]semaphore
	maxRequests int
}

func newHostThrottler(maxRequests int) *hostThrottler {
	return &hostThrottler{
		semaphores:  make(map[string]semaphore),
		maxRequests: maxRequests,
	}
}

func (h *hostThrottler) throttle(host string) semaphore {
	h.mutex.Lock()
	defer h.mutex.Unlock()
	s, ok := h.semaphores[host]
	if !ok {
		s = newSemaphore(h.maxRequests)
		h.semaphores[host] = s
	}
	return s
}

// Request acquires one slot of the semaphore for the given host.
func (h *hostThrottler) Request(host string) {
	s := h.throttle(host)
	s.Request()
}

// Release frees one slot of the semaphore for the given host.
func (h *hostThrottler) Release(host string) {
	h.throttle(host).Release()
}
