package main

import (
	"fmt"
	"strconv"
	"strings"
)

type statusRange struct {
	ranges [][2]int
	values []int
}

func (r statusRange) contains(code int) bool {
	for _, v := range r.values {
		if v == code {
			return true
		}
	}
	for _, rg := range r.ranges {
		if rg[0] <= code && code <= rg[1] {
			return true
		}
	}
	return false
}

func parseStatusRange(s string) (statusRange, error) {
	r := statusRange{}
	for _, element := range strings.Split(s, ",") {
		if strings.Contains(element, "..") {
			parts := strings.Split(element, "..")
			if len(parts) != 2 {
				return r, fmt.Errorf("invalid status code range: %s", element)
			}
			from, err := strconv.Atoi(parts[0])
			if err != nil {
				return r, fmt.Errorf("invalid status code: %s", parts[0])
			}
			to, err := strconv.Atoi(parts[1])
			if err != nil {
				return r, fmt.Errorf("invalid status code: %s", parts[1])
			}
			r.ranges = append(r.ranges, [2]int{from, to})
			continue
		}
		code, err := strconv.Atoi(element)
		if err != nil {
			return r, fmt.Errorf("invalid status code range: %s", element)
		}
		r.values = append(r.values, code)
	}
	return r, nil
}
