{"command": "cd /workspace && cat > scraper.go <<'GOEOF'
package main

import (
	"bytes"
	"html"
	"net/url"
	"strings"
)

type linkAttrs struct {
	tag  string
	name string
}

var scrapableAttrs = map[string][]string{
	"a":      {"href"},
	"img":    {"src"},
	"link":   {"href"},
	"script": {"src"},
	"iframe": {"src"},
	"source": {"src", "srcset"},
	"track":  {"src"},
}

var rawTextTags = map[string]bool{
	"script":    true,
	"style":     true,
	"xmp":       true,
	"iframe":    true,
	"noembed":   true,
	"noframes":  true,
	"noscript":  true,
	"textarea":  true,
	"title":     true,
	"plaintext": true,
}

type scrapedDoc struct {
	base      string
	hasBase   bool
	hrefs     []string
	ids       map[string]struct{}
}

// scrape parses the HTML document and extracts the base URL, the link URLs and
// the element identifiers.
func scrape(body []byte) *scrapedDoc {
	doc := &scrapedDoc{ids: make(map[string]struct{})}
	s := body
	i := 0
	n := len(s)
	for i < n {
		j := bytes.IndexByte(s[i:], '<')
		if j < 0 {
			break
		}
		i += j
		if i+3 < n && s[i+1] == '!' && s[i+2] == '-' && s[i+3] == '-' {
			k := i + 4
			for k+2 < n {
				if s[k] == '-' && s[k+1] == '-' && s[k+2] == '>' {
					break
				}
				k++
			}
			if k+2 >= n {
				break
			}
			i = k + 3
			continue
		}
		if i+1 < n && (s[i+1] == '!' || s[i+1] == '?') {
			k := i + 2
			for k < n && s[k] != '>' {
				k++
			}
			if k >= n {
				break
			}
			i = k + 1
			continue
		}
		if i+2 < n && s[i+1] == '/' && isAlphaByte(s[i+2]) {
			k := i + 2
			for k < n && isTagNameByte(s[k]) {
				k++
			}
			for k < n && s[k] != '>' {
				k++
			}
			if k >= n {
				break
			}
			i = k + 1
			continue
		}
		if i+1 >= n || !isAlphaByte(s[i+1]) {
			i++
			continue
		}
		k := i + 1
		for k < n && isTagNameByte(s[k]) {
			k++
		}
		name := strings.ToLower(string(s[i+1 : k]))
		attrs, selfClosing, next := parseAttributes(s, k)
		i = next

		switch name {
		case "base":
			if !doc.hasBase {
				if value, ok := attrValue(attrs, "href"); ok && strings.TrimSpace(value) != "" {
					doc.base = strings.TrimSpace(value)
					doc.hasBase = true
				}
			}
		}
		if names, ok := scrapableAttrs[name]; ok {
			for _, attr := range names {
				value, ok := attrValue(attrs, attr)
				if !ok {
					continue
				}
				if attr == "srcset" {
					doc.hrefs = append(doc.hrefs, parseSrcSet(value)...)
					continue
				}
				doc.hrefs = append(doc.hrefs, strings.TrimSpace(value))
			}
		}
		if value, ok := attrValue(attrs, "id"); ok {
			doc.ids[value] = struct{}{}
		}

		if rawTextTags[name] && !selfClosing {
			if name == "plaintext" {
				break
			}
			i = skipRawText(s, i, name)
		}
	}
	return doc
}

func isAlphaByte(c byte) bool {
	return 'a' <= c && c <= 'z' || 'A' <= c && c <= 'Z'
}

func isTagNameByte(c byte) bool {
	return isAlphaByte(c) || '0' <= c && c <= '9' || c == '-' || c == '_' || c == ':' || c == '.'
}

func isWhitespaceByte(c byte) bool {
	switch c {
	case ' ', '\t', '\n', '\f', '\r':
		return true
	}
	return false
}

func parseAttributes(s []byte, i int) ([][2]string, bool, int) {
	var attrs [][2]string
	selfClosing := false
	n := len(s)
	for i < n {
		for i < n && isWhitespaceByte(s[i]) {
			i++
		}
		if i >= n {
			break
		}
		if s[i] == '>' {
			i++
			break
		}
		if s[i] == '/' {
			if i+1 < n && s[i+1] == '>' {
				selfClosing = true
				i += 2
				break
			}
			i++
			continue
		}
		start := i
		for i < n && !isWhitespaceByte(s[i]) && s[i] != '=' && s[i] != '>' {
			i++
		}
		if i == start {
			i++
			continue
		}
		name := strings.ToLower(html.UnescapeString(string(s[start:i])))
		for i < n && isWhitespaceByte(s[i]) {
			i++
		}
		value := ""
		if i < n && s[i] == '=' {
			i++
			for i < n && isWhitespaceByte(s[i]) {
				i++
			}
			if i < n && (s[i] == '"' || s[i] == '\'') {
				quote := s[i]
				i++
				start := i
				for i < n && s[i] != quote {
					i++
				}
				value = html.UnescapeString(string(s[start:i]))
				if i < n {
					i++
				}
			} else {
				start := i
				for i < n && !isWhitespaceByte(s[i]) && s[i] != '>' {
					i++
				}
				value = html.UnescapeString(string(s[start:i]))
			}
		}
		attrs = append(attrs, [2]string{name, value})
	}
	return attrs, selfClosing, i
}

func attrValue(attrs [][2]string, name string) (string, bool) {
	for _, a := range attrs {
		if a[0] == name {
			return a[1], true
		}
	}
	return "", false
}

func lowerByte(c byte) byte {
	if 'A' <= c && c <= 'Z' {
		return c + 'a' - 'A'
	}
	return c
}

func skipRawText(s []byte, i int, name string) int {
	target := []byte(name)
	n := len(s)
	for i+1 < n {
		if s[i] != '<' || s[i+1] != '/' {
			i++
			continue
		}
		k := i + 2
		j := 0
		for j < len(target) && k < n && lowerByte(s[k]) == target[j] {
			k++
			j++
		}
		if j == len(target) && (k >= n || isWhitespaceByte(s[k]) || s[k] == '>' || s[k] == '/') {
			for k < n && s[k] != '>' {
				k++
			}
			if k >= n {
				return n
			}
			return k + 1
		}
		i++
	}
	return n
}

// parseSrcSet splits a srcset attribute value into candidate URLs.
func parseSrcSet(value string) []string {
	var out []string
	for _, part := range strings.Split(value, ", ") {
		part = strings.TrimSpace(part)
		if part == "" {
			continue
		}
		fields := strings.Fields(part)
		if len(fields) > 1 {
			part = strings.Join(fields[:len(fields)-1], " ")
		}
		out = append(out, part)
	}
	return out
}

// resolveLinks turns the raw attribute values into URLs, applying the document
// base URL.
func resolveLinks(doc *scrapedDoc, pageURL *url.URL) []*url.URL {
	base := pageURL
	if doc.hasBase {
		if ref, err := url.Parse(doc.base); err == nil {
			base = pageURL.ResolveReference(ref)
		}
	}
	var out []*url.URL
	for _, href := range doc.hrefs {
		if href == "" {
			continue
		}
		ref, err := url.Parse(href)
		if err != nil {
			continue
		}
		out = append(out, base.ResolveReference(ref))
	}
	return out
}
