package main

import "regexp"

type verifier struct {
	excludes []*regexp.Regexp
	includes []*regexp.Regexp
}

func newVerifier(excludes, includes []string) (*verifier, error) {
	v := &verifier{}
	for _, pattern := range excludes {
		re, err := regexp.Compile(pattern)
		if err != nil {
			return nil, err
		}
		v.excludes = append(v.excludes, re)
	}
	for _, pattern := range includes {
		re, err := regexp.Compile(pattern)
		if err != nil {
			return nil, err
		}
		v.includes = append(v.includes, re)
	}
	return v, nil
}

func (v *verifier) verify(s string) bool {
	for _, re := range v.excludes {
		if re.MatchString(s) {
			return false
		}
	}
	if len(v.includes) == 0 {
		return true
	}
	for _, re := range v.includes {
		if re.MatchString(s) {
			return true
		}
	}
	return false
}
GOEOF
