{"command": "cd /workspace && cat > output.go <<'GOEOF'
package main

import (
	"encoding/json"
	"encoding/xml"
	"fmt"
	"sort"
	"strconv"
	"strings"
	"sync"
)

const (
	colorYellow = 33
	colorGreen  = 32
	colorRed    = 31
)

type output struct {
	options *options
	color   bool
	mutex   sync.Mutex
	pages   []*page
	index   map[string]*page
	failed  bool
}

func newOutput(options *options) *output {
	color := false
	switch options.Color {
	case "always":
		color = true
	case "never":
		color = false
	default:
		color = isTerminal(1)
	}
	return &output{options: options, color: color, index: make(map[string]*page)}
}

func isTerminal(fd int) bool {
	var ws struct{ rows, cols, x, y uint16 }
	_, _, errno := syscallIoctl(uintptr(fd), uintptr(syscallTIOCGWINSZ), uintptr(toPointer(&ws)))
	return errno == 0
}

func colorize(s string, code int, enable bool) string {
	if !enable {
		return s
	}
	return "\x1b[" + strconv.Itoa(code) + "m" + s + "\x1b[0m"
}

func (o *output) addPage(p *page) {
	o.mutex.Lock()
	defer o.mutex.Unlock()
	o.pages = append(o.pages, p)
	o.index[p.url] = p
	for _, l := range p.links {
		if l.err != nil {
			o.failed = true
		}
	}
	if o.options.Format == "json" || o.options.JSON {
		return
	}
	if o.options.Format == "junit" || o.options.JUnit {
		return
	}
	verbose := o.options.Verbose
	if verbose || o.hasFailure(p) {
		fmt.Println(colorize(p.url, colorYellow, o.color))
		for _, l := range o.sortLinks(p) {
			if !verbose && l.err == nil {
				continue
			}
			if l.err != nil {
				fmt.Printf("\t%s\t%s\n", colorize(l.err.Error(), colorRed, o.color), l.url)
				continue
			}
			fmt.Printf("\t%s\t%s\n", colorize(strconv.Itoa(l.status), colorGreen, o.color), l.url)
		}
	}
}

func (o *output) hasFailure(p *page) bool {
	for _, l := range p.links {
		if l.err != nil {
			return true
		}
	}
	return false
}

func (o *output) sortLinks(p *page) []*link {
	links := make([]*link, len(p.links))
	copy(links, p.links)
	sort.Slice(links, func(i, j int) bool {
		a, b := links[i], links[j]
		var ae, be string
		if a.err != nil {
			ae = a.err.Error()
		}
		if b.err != nil {
			be = b.err.Error()
		}
		if ae != be {
			return ae < be
		}
		return a.url < b.url
	})
	return links
}

func (o *output) addLink(p *page, l *link) {
	o.mutex.Lock()
	defer o.mutex.Unlock()
	if l.err != nil {
		o.failed = true
	}
}

func (o *output) isFailed() bool {
	return o.failed
}

func (o *output) flush() {
	format := "text"
	if o.options.JSON {
		format = "json"
	} else if o.options.JUnit {
		format = "junit"
	} else {
		format = o.options.Format
	}
	switch format {
	case "json":
		o.printJSON()
	case "junit":
		o.printJUnit()
	}
}

type jsonLink struct {
	URL    string `json:"url"`
	Status *int   `json:"status,omitempty"`
	Error  string `json:"error,omitempty"`
}

type jsonPage struct {
	URL   string     `json:"url"`
	Links []jsonLink `json:"links"`
}

func (o *output) printJSON() {
	verbose := o.options.Verbose || (o.options.JSON && o.options.ExperimentalVerboseJSON)
	byURL := make(map[string]*page)
	for _, p := range o.pages {
		byURL[p.url] = p
	}
	var pages []jsonPage
	for _, p := range byURL {
		if !verbose && !o.hasFailure(p) {
			continue
		}
		linksByKey := make(map[string]*link)
		for _, l := range p.links {
			linksByKey[l.url] = l
		}
		var links []jsonLink
		for _, l := range linksByKey {
			if !verbose && l.err == nil {
				continue
			}
			jl := jsonLink{URL: l.url}
			if l.err != nil {
