package main

import (
	"errors"
	"fmt"
	"os"
	"strings"
)

// command is the root command of the application.
type command struct {
	options *options
}

func newCommand() *command {
	return &command{options: newOptions()}
}

// Run parses the given arguments and runs the command. It returns the exit code.
func (c *command) Run(args []string) int {
	positional, err := c.options.parse(args)
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		return 1
	}
	if c.options.Help {
		c.options.writeHelp(program)
		return 0
	}
	if c.options.Version {
		fmt.Println(version)
		return 0
	}
	if len(positional) != 1 {
		fmt.Fprintln(os.Stderr, "invalid number of arguments")
		return 1
	}
	if err := c.runWithError(positional[0]); err != nil {
		if err != errFailure {
			fmt.Fprintln(os.Stderr, err)
		}
		return 1
	}
	return 0
}

var errFailure = errors.New("failure")

// runWithError runs the command and returns an error if any.
func (c *command) runWithError(url string) error {
	options := c.options

	if (options.Format == "junit" || options.JUnit) && options.Verbose {
		return errors.New("verbose option not supported for JUnit output")
	}

	accepted, err := parseStatusRange(options.AcceptedStatusCodes)
	if err != nil {
		return err
	}
	for _, header := range options.Header {
		if !strings.Contains(header, ":") {
			return errors.New("invalid header format")
		}
	}
	verifier, err := newVerifier(options.Exclude, options.Include)
	if err != nil {
		return err
	}

	client := newHTTPClient(options)
	throttled := &throttledHttpClient{
		client:        client,
		semaphore:     newSemaphore(options.MaxConnections),
		hostThrottler: newHostThrottler(options.MaxConnectionsPerHost),
		rateLimiter:   newRateLimiter(options.RateLimit),
	}
	retry := &retryHttpClient{client: throttled, maxRetries: options.MaxRetries}
	redirect := &redirectHttpClient{client: retry, maxRedirections: options.MaxRedirections}
	checked := &checkedHttpClient{client: redirect, accepted: accepted}

	output := newOutput(options)
	fetcher := newLinkFetcher(checked, options, verifier, output)
	if err := fetcher.Fetch(url); err != nil {
		return fmt.Errorf("failed to fetch root page: %v", err)
	}
	if output.isFailed() {
		return errFailure
	}
	return nil
}
