package main

import (
	"net/url"
	"strings"
	"sync"
)

// link is a checked URL found in a page.
type link struct {
	url    string
	err    error
	status int
}

// page is a fetched document.
type page struct {
	url         string
	status      int
	err         error
	contentType string
	fetched     chan struct{}
	ids         map[string]struct{}
	hrefs       []string
	hasBase     bool
	base        string
	links       []*link
	linkMutex   sync.Mutex
	dispatched  bool
	wg          sync.WaitGroup
}

func (p *page) addLink(l *link) {
	p.linkMutex.Lock()
	defer p.linkMutex.Unlock()
	p.links = append(p.links, l)
}

func (p *page) isHTML() bool {
	return isHTML(p.contentType)
}

type linkFetcher struct {
	client   httpClientInterface
	options  *options
	verifier *verifier
	pages    map[string]*page
	mutex    sync.Mutex
	output   *output
	wg       sync.WaitGroup
}

func newLinkFetcher(client httpClientInterface, options *options, verifier *verifier, output *output) *linkFetcher {
	return &linkFetcher{
		client:   client,
		options:  options,
		verifier: verifier,
		pages:    make(map[string]*page),
		output:   output,
	}
}

func isHTML(contentType string) bool {
	mediaType := contentType
	if i := strings.IndexByte(mediaType, ';'); i >= 0 {
		mediaType = mediaType[:i]
	}
	return strings.EqualFold(strings.TrimSpace(mediaType), "text/html")
}

func (f *linkFetcher) getOrCreatePage(pageURL string) *page {
	f.mutex.Lock()
	defer f.mutex.Unlock()
	if p, ok := f.pages[pageURL]; ok {
		return p
	}
	p := &page{url: pageURL, fetched: make(chan struct{})}
	f.pages[pageURL] = p
	f.wg.Add(1)
	go f.fetchPage(p)
	return p
}

func (f *linkFetcher) fetchPage(p *page) {
	defer f.wg.Done()
	resp, err := f.client.Get(p.url)
	if err != nil {
		p.err = err
		close(p.fetched)
		return
	}
	p.status = resp.status
	p.contentType = resp.contentType
	if isHTML(resp.contentType) {
		doc := scrape(resp.body)
		p.ids = doc.ids
		p.hrefs = doc.hrefs
		p.hasBase = doc.hasBase
		p.base = doc.base
	}
	close(p.fetched)
}

// dispatch extracts the links of the page and checks them. It is idempotent.
func (f *linkFetcher) dispatch(p *page) {
	f.mutex.Lock()
	if p.dispatched {
		f.mutex.Unlock()
		return
	}
	p.dispatched = true
	f.mutex.Unlock()

	if f.options.OnePageOnly {
		f.output.addPage(p)
		return
	}

	base := f.pageBaseURL(p)
	seen := make(map[string]struct{})
	var pending []string
	for _, href := range p.hrefs {
		u, err := f.resolve(href, base)
		if err != nil {
			l := &link{url: href, err: err}
			p.addLink(l)
			f.output.addLink(p, l)
			continue
		}
		reported := u.String()
		filtered := reported
		if f.options.IgnoreFragments {
			filtered = stripFragment(reported)
		}
		if !f.verifier.verify(filtered) {
			continue
		}
		if _, ok := seen[reported]; ok {
			continue
		}
		seen[reported] = struct{}{}
		pending = append(pending, reported)
	}

	p.wg.Add(len(pending))
	for _, u := range pending {
		f.wg.Add(1)
		go f.checkLink(p, u)
	}
	f.wg.Add(1)
	go func() {
		defer f.wg.Done()
		p.wg.Wait()
		f.output.addPage(p)
	}()
}

func (f *linkFetcher) pageBaseURL(p *page) *url.URL {
	u, err := url.Parse(p.url)
	if err != nil {
		u = &url.URL{}
	}
	if p.hasBase {
		if ref, err := url.Parse(p.base); err == nil {
			u = u.ResolveReference(ref)
		}
	}
	return u
}

func (f *linkFetcher) resolve(href string, base *url.URL) (*url.URL, error) {
	ref, err := url.Parse(href)
	if err != nil {
		return nil, err
	}
	switch ref.Scheme {
	case "http", "https":
	default:
		return nil, errSkipped
	}
	return base.ResolveReference(ref), nil
}

var errSkipped = &skippedError{}

type skippedError struct{}

func (e *skippedError) Error() string { return "skipped" }

func (f *linkFetcher) checkLink(parent *page, reported string) {
	defer parent.wg.Done()
	defer f.wg.Done()

	fragment := fragmentOf(reported)
	pageURL := stripFragment(reported)

	target := f.getOrCreatePage(pageURL)
	<-target.fetched

	l := &link{url: reported}
	if target.err != nil {
		l.err = target.err
	} else if fragment != "" && target.ids != nil {
		if _, ok := target.ids[fragment]; !ok {
			l.err = &fragmentError{fragment: fragment}
		} else {
			l.status = target.status
		}
	} else {
		l.status = target.status
	}
	parent.addLink(l)
	f.output.addLink(parent, l)

	if target.err == nil && target.isHTML() {
		f.dispatch(target)
	}
}

// Fetch checks the given URL and all the pages reachable from it.
func (f *linkFetcher) Fetch(rootURL string) error {
	root := f.getOrCreatePage(rootURL)
	<-root.fetched
	if root.err != nil {
		return root.err
	}
	if f.options.FollowRobotsTxt {
		if err := f.fetchRobotsTxt(rootURL); err != nil {
			return err
		}
	}
	if f.options.FollowSitemapXML {
		if err := f.fetchSitemapXML(rootURL); err != nil {
			return err
		}
	}
	f.dispatch(root)
	f.wg.Wait()
	f.output.flush()
	return nil
}

func (f *linkFetcher) fetchRobotsTxt(rootURL string) error {
	u, err := url.Parse(rootURL)
	if err != nil {
		return err
	}
	u.Path = "/robots.txt"
	u.RawQuery = ""
	u.Fragment = ""
	_, err = f.client.Get(u.String())
	return err
}

func (f *linkFetcher) fetchSitemapXML(rootURL string) error {
	u, err := url.Parse(rootURL)
	if err != nil {
		return err
	}
	u.Path = "/sitemap.xml"
	u.RawQuery = ""
	u.Fragment = ""
	_, err = f.client.Get(u.String())
	return err
}
