new = '''// bodyReader reads the response body from the connection.
type bodyReader struct {
	reader *bufio.Reader
	rest   []byte
	read   int
	max    int
}

func (b *bodyReader) fill() {
	if len(b.rest) == 0 {
		data, err := b.reader.Peek(b.reader.Size())
		if len(data) > 0 {
			b.rest = append(b.rest, data...)
			b.reader.Discard(len(data))
		}
		if err != nil && err != io.EOF && err != bufio.ErrBufferFull {
			// ignore
		}
	}
}

func (b *bodyReader) readByte() (byte, error) {
	if len(b.rest) == 0 {
		b.fill()
		if len(b.rest) == 0 {
			return 0, io.EOF
		}
	}
	c := b.rest[0]
	b.rest = b.rest[1:]
	b.read++
	return c, nil
}

func (b *bodyReader) read(n int) ([]byte, error) {
	var out []byte
	for len(out) < n {
		if len(b.rest) == 0 {
			b.fill()
			if len(b.rest) == 0 {
				return out, io.EOF
			}
		}
		take := n - len(out)
		if take > len(b.rest) {
			take = len(b.rest)
		}
		out = append(out, b.rest[:take]...)
		b.rest = b.rest[take:]
		b.read += take
	}
	return out, nil
}

func (b *bodyReader) readLine() ([]byte, error) {
	for {
		if i := bytes.Index(b.rest, crlf); i >= 0 {
			line := b.rest[:i]
			b.rest = b.rest[i+2:]
			b.read += i + 2
			return line, nil
		}
		before := len(b.rest)
		b.fill()
		if len(b.rest) == before {
			line := b.rest
			b.rest = nil
			b.read += len(line)
			if len(line) == 0 {
				return nil, io.EOF
			}
			return line, io.EOF
		}
	}
}

func (b *bodyReader) available() []byte {
	return b.rest
}

var crlf = []byte("\\r\\n")

func parseChunkSize(line []byte) (int64, error) {
	if i := bytes.IndexByte(line, ';'); i >= 0 {
		line = line[:i]
	}
	i := 0
	var value int64
	for i < len(line) {
		c := line[i]
		var digit int64
		switch {
		case '0' <= c && c <= '9':
			digit = int64(c - '0')
		case 'a' <= c && c <= 'f':
			digit = int64(c-'a') + 10
		case 'A' <= c && c <= 'F':
			digit = int64(c-'A') + 10
		default:
			i = len(line)
		}
		if digit == 0 && i == len(line) {
			break
		}
		value = value*16 + digit
		i++
		if i >= len(line) {
			break
		}
		if !isHexByte(line[i]) {
			break
		}
	}
	if i == 0 {
		return 0, errors.New("empty hex number")
	}
	return value, nil
}

func isHexByte(c byte) bool {
	return '0' <= c && c <= '9' || 'a' <= c && c <= 'f' || 'A' <= c && c <= 'F'
}

func readBody(reader *bufio.Reader, rest []byte, h *respHeader, maxSize int) ([]byte, error) {
	if maxSize <= 0 {
		maxSize = 1 << 30
	}
	br := &bodyReader{reader: reader, rest: rest, max: maxSize}
	var body []byte
	add := func(data []byte) error {
		if len(body)+len(data) > maxSize {
			return errors.New("body size exceeds the given limit")
		}
		body = append(body, data...)
		return nil
	}
	if h.chunked {
		for {
			line, err := br.readLine()
			if err == io.EOF {
				break
			}
			if err != nil {
				return nil, err
			}
			size, err := parseChunkSize(line)
			if err != nil {
				return nil, err
			}
			if size == 0 {
				if err := readTrailers(br); err != nil {
					return nil, err
				}
				break
			}
			data, err := br.read(int(size))
			if err != nil {
				return nil, errors.New("unexpected EOF")
			}
			if err := add(data); err != nil {
				return nil, err
			}
			crlf, err := br.read(2)
			if err != nil {
				return nil, errors.New("unexpected EOF")
			}
			if !bytes.Equal(crlf, crlfBytes) {
				return nil, errors.New("cannot find crlf at the end of chunk")
			}
		}
		return body, nil
	}
	if h.hasContentLength {
		data, err := br.read(int(h.contentLength))
		if err != nil {
			return nil, errors.New("unexpected EOF")
		}
		if err := add(data); err != nil {
			return nil, err
		}
		return body, nil
	}
	for {
		data, err := br.read(4096)
		if len(data) > 0 {
			if err := add(data); err != nil {
				return nil, err
			}
		}
		if err != nil {
			break
		}
	}
	return body, nil
}

var crlfBytes = []byte("\\r\\n")

func readTrailers(br *bodyReader) error {
	available := append([]byte{}, br.available()...)
	for {
		line, err := br.readLine()
		if err == io.EOF {
			return nil
		}
		if err != nil {
			return nil
		}
		if len(line) == 0 {
			return nil
		}
		if bytes.IndexByte(line, ':') < 0 {
			return headerError(fmt.Errorf("malformed MIME header: missing colon: %q", line), available)
		}
	}
}

