package main

import (
	"errors"
	"fmt"
	"net"
	"sync"
)

// resolver resolves host names to IP addresses with a cache and retries.
type resolver struct {
	maxRetries uint
	mutex      sync.Mutex
	cache      map[string][]net.IP
}

func newResolver(maxRetries uint, dnsServer string) *resolver {
	r := &resolver{maxRetries: maxRetries, cache: make(map[string][]net.IP)}
	if dnsServer != "" {
		r.resolver = &net.Resolver{
			PreferGo: true,
			Dial: func(ctx context, network, addr string) (net.Conn, error) {
				var dialer net.Dialer
				return dialer.DialContext(ctx, "udp", dnsServer)
			},
		}
	}
	return r
}

func (r *resolver) lookup(host string) ([]net.IP, error) {
	r.mutex.Lock()
	ips, ok := r.cache[host]
	r.mutex.Unlock()
	if ok {
		return ips, nil
	}
	resolved, err := lookupIPAddr(r.resolver, host)
	if err != nil {
		return nil, err
	}
	var ipv4, ipv6 []net.IP
	for _, addr := range resolved {
		ip := addr.IP
		if ip.To4() != nil {
			ipv4 = append(ipv4, ip)
		} else {
			ipv6 = append(ipv6, ip)
		}
	}
	ips = append(ipv4, ipv6...)
	r.mutex.Lock()
	r.cache[host] = ips
	r.mutex.Unlock()
	return ips, nil
}

// lookupWithRetries resolves the host, retrying on DNS errors.
func (r *resolver) lookupWithRetries(host string) ([]net.IP, error) {
	ips, err := r.lookup(host)
	if err == nil {
		return ips, nil
	}
	var dnsErr *net.DNSError
	if !errors.As(err, &dnsErr) || r.maxRetries == 0 {
		return nil, err
	}
	for attempt := uint(1); ; attempt++ {
		ips, err = r.lookup(host)
		if err == nil {
			return ips, nil
		}
		if !errors.As(err, &dnsErr) {
			return nil, err
		}
		if attempt >= r.maxRetries {
			return nil, fmt.Errorf("max retry count %d exceeded: %v", r.maxRetries, err)
		}
	}
}
GOEOF
