{"command": "cd /workspace && cat > link_fetcher.go <<'GOEOF'
package main

import (
	"errors"
	"net"
	"net/url"
	"strings"
	"sync"
)

// link is a checked URL found in a page.
type link struct {
	url    string
	err    error
	status int
}

// page is a fetched document.
type page struct {
	url         string
	fetchURL    string
	status      int
	err         error
	contentType string
	fetched     chan struct{}
	ids         map[string]struct{}
	hrefs       []string
	hasBase     bool
	base        string
	links       []*link
	isRoot      bool
	linkMutex   sync.Mutex
	dispatched  bool
	wg          sync.WaitGroup
}

func (p *page) addLink(l *link) {
	p.linkMutex.Lock()
	defer p.linkMutex.Unlock()
	p.links = append(p.links, l)
}

func (p *page) isHTML() bool {
	return isHTML(p.contentType)
}

type linkFetcher struct {
	client   httpClientInterface
	options  *options
	verifier *verifier
	resolver *resolver
	pages    map[string]*page
	sitemap  map[string]struct{}
	mutex    sync.Mutex
	output   *output
	wg       sync.WaitGroup
}

func newLinkFetcher(client httpClientInterface, options *options, verifier *verifier, resolver *resolver, output *output) *linkFetcher {
	return &linkFetcher{
		client:   client,
		options:  options,
		verifier: verifier,
		resolver: resolver,
		pages:    make(map[string]*page),
		output:   output,
	}
}

func isHTML(contentType string) bool {
	mediaType := contentType
	if i := strings.IndexByte(mediaType, ';'); i >= 0 {
		mediaType = mediaType[:i]
	}
	return strings.EqualFold(strings.TrimSpace(mediaType), "text/html")
}

func (f *linkFetcher) getOrCreatePage(pageURL, fetchURL string) *page {
	f.mutex.Lock()
	defer f.mutex.Unlock()
	if p, ok := f.pages[pageURL]; ok {
		return p
	}
	if fetchURL == "" {
		fetchURL = pageURL
	}
	p := &page{url: pageURL, fetchURL: fetchURL, fetched: make(chan struct{})}
	f.pages[pageURL] = p
	f.wg.Add(1)
	go f.fetchPage(p)
	return p
}

func (f *linkFetcher) fetchPage(p *page) {
	defer f.wg.Done()
	resp, err := f.client.Get(p.fetchURL)
	if err != nil {
		p.err = err
		close(p.fetched)
		return
	}
	p.status = resp.status
	p.contentType = resp.contentType
	if isHTML(resp.contentType) {
		doc := scrape(resp.body)
		p.ids = doc.ids
		p.hrefs = doc.hrefs
		p.hasBase = doc.hasBase
		p.base = doc.base
	}
	close(p.fetched)
}

// canonical returns the URL of the page as stored by the fetcher: the host is
// replaced with the resolved IP address and the fragment is removed.
func canonical(u *url.URL, ips []net.IP) (string, error) {
	scheme := u.Scheme
	if scheme == "" {
		scheme = "http"
	}
	host := u.Hostname()
	port := u.Port()
	if len(ips) == 0 {
		return "", errors.New("couldn't find DNS entries for the given domain. Try using DialDualStack")
	}
	address := ips[0].String()
	if port != "" {
		if strings.Contains(address, ":") {
			address = "[" + address + "]:" + port
		} else {
			address = address + ":" + port
		}
	}
	out := url.URL{Scheme: scheme, Host: address, Path: u.Path, RawPath: u.RawPath, RawQuery: u.RawQuery}
	return out.String(), nil
}

func (f *linkFetcher) pageFor(rawurl string) (*page, *url.URL, error) {
	u, err := url.Parse(rawurl)
	if err != nil {
		return nil, nil, err
	}
	if u.Scheme != "" && u.Scheme != "http" && u.Scheme != "https" {
		return nil, nil, errSkipped
	}
	var ips []net.IP
	if u.Hostname() != "" {
		ips, err = f.resolver.lookupWithRetries(u.Hostname())
		if err != nil {
			return nil, nil, err
		}
	}
	pageURL, err := canonical(u, ips)
	if err != nil {
		return nil, nil, err
	}
	fetchURL := *u
	fetchURL.Fragment = ""
	fetchURL.RawFragment = ""
	return f.getOrCreatePage(pageURL, fetchURL.String()), u, nil
}

// dispatch extracts the links of the page and checks them. It is idempotent.
func (f *linkFetcher) dispatch(p *page) {
	f.mutex.Lock()
	if p.dispatched {
		f.mutex.Unlock()
		return
	}
	p.dispatched = true
	f.mutex.Unlock()

	if !f.shouldScrape(p) {
		return
	}

	base := f.pageBaseURL(p)
	seen := make(map[string]struct{})
	var pending []string
	for _, href := range p.hrefs {
		u, err := f.resolve(href, base)
		if err == errSkipped {
			continue
		}
		if err != nil {
			l := &link{url: href, err: err}
			p.addLink(l)
			f.output.addLink(p, l)
			continue
		}
		reported := u.String()
		filtered := reported
		if f.options.IgnoreFragments {
			filtered = stripFragment(reported)
		}
		if !f.verifier.verify(filtered) {
			continue
		}
		if _, ok := seen[reported]; ok {
			continue
		}
		seen[reported] = struct{}{}
		pending = append(pending, reported)
	}

	p.wg.Add(len(pending))
	for _, u := range pending {
		f.wg.Add(1)
		go f.checkLink(p, u)
	}
	f.wg.Add(1)
	go func() {
		defer f.wg.Done()
		p.wg.Wait()
		f.output.addPage(p)
	}()
}

func (f *linkFetcher) pageBaseURL(p *page) *url.URL {
	u, err := url.Parse(p.url)
	if err != nil {
		u = &url.URL{}
	}
	if p.hasBase {
		if ref, err := url.Parse(p.base); err == nil {
			u = u.ResolveReference(ref)
		}
	}
	return u
}

func (f *linkFetcher) resolve(href string, base *url.URL) (*url.URL, error) {
	ref, err := url.Parse(href)
	if err != nil {
		return nil, err
	}
	if ref.Scheme != "" && ref.Scheme != "http" && ref.Scheme != "https" {
		return nil, errSkipped
	}
	return base.ResolveReference(ref), nil
}

var errSkipped = &skippedError{}

type skippedError struct{}

func (e *skippedError) Error() string { return "skipped" }

func (f *linkFetcher) checkLink(parent *page, reported string) {
	defer parent.wg.Done()
	defer f.wg.Done()

	fragment := fragmentOf(reported)

	target, _, err := f.pageFor(reported)
	if err != nil {
		l := &link{url: reported, err: err}
		parent.addLink(l)
		f.output.addLink(parent, l)
		return
	}
	<-target.fetched

	l := &link{url: reported}
	if target.err != nil {
		l.err = target.err
	} else if fragment != "" && target.ids != nil {
		if _, ok := target.ids[fragment]; !ok {
			l.err = &fragmentError{fragment: fragment}
		} else {
			l.status = target.status
		}
	} else {
		l.status = target.status
	}
	parent.addLink(l)
	f.output.addLink(parent, l)

	if target.err == nil && target.isHTML() {
		f.dispatch(target)
	}
}

// shouldScrape reports whether the links of the page should be scraped.
func (f *linkFetcher) shouldScrape(p *page) bool {
	if p.isRoot {
		return true
	}
	if f.options.OnePageOnly {
		return false
	}
	if f.options.FollowSitemapXML {
		_, ok := f.sitemap[p.url]
		return ok
	}
	return true
}

// Fetch checks the given URL and all the pages reachable from it.
func (f *linkFetcher) Fetch(rawurl string) error {
	root, u, err := f.pageFor(rawurl)
	if err != nil {
		return err
	}
	fragment := u.Fragment
	normalized := *u
	normalized.User = nil
	if normalized.Scheme == "" {
		normalized.Scheme = "http"
	}
	rootURL := normalized.String()

	root.isRoot = true
	<-root.fetched
	if root.err != nil {
		return root.err
	}
	if f.options.FollowRobotsTxt {
		if err := f.fetchRobotsTxt(rootURL); err != nil {
			return &fetchError{msg: "failed to fetch robots.txt: " + err.Error()}
		}
	}
	if f.options.FollowSitemapXML {
		body, err := f.fetchSitemapXML(rootURL)
		if err != nil {
			return &fetchError{msg: "failed to GET sitemap.xml: " + err.Error()}
		}
		urls, err := parseSitemap(body)
		if err != nil {
			return &fetchError{msg: "failed to parse sitemap.xml: " + err.Error()}
		}
		f.mutex.Lock()
		f.sitemap = urls
		f.mutex.Unlock()
	}
	if fragment != "" && root.ids != nil {
		if _, ok := root.ids[fragment]; !ok {
			return &fragmentError{fragment: fragment}
		}
	}
	f.dispatch(root)
	f.wg.Wait()
	f.output.flush()
	return nil
}

func (f *linkFetcher) fetchRobotsTxt(rootURL string) error {
	u, err := url.Parse(rootURL)
	if err != nil {
		return err
	}
	u.Path = "/robots.txt"
	u.RawQuery = ""
	u.Fragment = ""
	_, err = f.client.Get(u.String())
	return err
}

func (f *linkFetcher) fetchSitemapXML(rootURL string) ([]byte, error) {
	u, err := url.Parse(rootURL)
	if err != nil {
		return nil, err
	}
	u.Path = "/sitemap.xml"
	u.RawQuery = ""
	u.Fragment = ""
	resp, err := f.client.Get(u.String())
	if err != nil {
		return nil, err
	}
	return resp.body, nil
}
